import{applyFollowupRound063}from'./followup-063-replay.js';
import{explorerResults as originalResults,explorerCareerQuestions,explorerFieldQuestions,explorerAnswer,explorerEducation,resolveExplorerRoute,explorerCatalog}from'./open-explorer.js';
import{careerFamilies}from'./guide-state.js';import{saveExplorerAnswer}from'./explorer-053-state.js';
import{discoveryTopics056,evidenceHolds056,explicitActivityLinks056,authoredActivityInputs056}from'./exploration-056-data.js';
export{explorerFieldQuestions,explorerCareerQuestions,explorerAnswer,explorerEducation,resolveExplorerRoute};
export{discoveryTopics056};
export const soundPreview056={id:'sound-engineering-056',title:'Sound Engineering Technicians',soc:'27-4014.00',summary:'Record, combine and revise sound; compare equipment setup, editing and collaboration on a production.',fields:['creative','technology'],education:'Training route varies; vocational, associate and some degree routes',degree:false,source:'https://www.onetonline.org/link/summary/27-4014.00',educationSource:'https://www.bls.gov/ooh/media-and-communication/broadcast-and-sound-engineering-technicians.htm',discoveryOnly:true};
export function applyModelContext056(state,c){const s=structuredClone(state);s._modelId056=c.id;s.explorer053??={version:1,facetAnswers:{},fieldAnswers:{},professionAnswers:{},history:[]};
 // Only explicitly authored option-ID inputs are applied. No biography, label or prompt text is classified.
 for(const input of authoredActivityInputs056.filter(a=>a.modelId===c.id)){const id='topic056-'+input.topic;if(s.explorer053.facetAnswers[id])continue;saveExplorerAnswer(s,{kind:'facet',questionId:id,payload:{value:4,source:'profile-inferred',confidence:'medium',evidence:input.quote},at:'2026-10-20T15:00:00.000Z'});}
 for(const h of evidenceHolds056.filter(h=>h.modelId===c.id)){const fresh=s.explorer053.professionAnswers?.[h.careerId]?.[h.questionId],old=fresh||s.profileJourney?.expandedInterests?.[h.questionId]||s.profileJourney?.coreWork?.[h.questionId];if(!old||old.source!=='profile-inferred'||old.response!=='yes'||fresh?.reviewHold)continue;saveExplorerAnswer(s,{kind:'profession',scope:h.careerId,questionId:h.questionId,payload:{...old,reviewHold:h.reason,reviewFollowup:h.followup},at:'2026-10-20T15:00:00.000Z'});}
 return applyFollowupRound063(s,c.id);
}
export function activityTopics056(s){return discoveryTopics056.filter(t=>{const a=s.explorer053?.facetAnswers?.['topic056-'+t.id];return a?.value>=4&&!a.reviewHold&&(a.source!=='profile-inferred'||['high','medium'].includes(a.confidence));});}
export function explorerResults(s,options={}){
 const original=originalResults(s,options),topics=activityTopics056(s),codes=new Set(topics.map(t=>t.id)),rows=original.rows.map(r=>{const matches=topics.filter(t=>explicitActivityLinks056[t.id]?.includes(r.id)).map(t=>t.id);return{...r,activityTopics:matches,activityStrength:matches.length};});
 if(options.sort==='correlation'||!topics.length)return{...original,rows,version:'0.56.0'};
 const supported=rows.filter(r=>r.specific.supported),remaining=rows.filter(r=>!r.specific.supported),selected=[],seen=new Set(supported.map(r=>r.id));
 // Round-robin invitations preserve distinct interests. Topics can never establish specific support.
 for(let round=0;round<2;round++)for(const t of topics){const candidates=remaining.filter(r=>!seen.has(r.id)&&!r.specific.contrary.length&&r.activityTopics.includes(t.id)).sort((a,b)=>b.activityStrength-a.activityStrength||(b.r??-2)-(a.r??-2)||a.id.localeCompare(b.id)),r=candidates[0];if(r){seen.add(r.id);selected.push(r);}}
 return{...original,version:'0.56.0',rows:[...supported,...selected,...remaining.filter(r=>!seen.has(r.id))]};
}
export function explorerFieldSummary(s){const rows=explorerResults(s).rows;return careerFamilies.map(f=>({id:f.id,title:f.title,careers:rows.filter(r=>r.fields.includes(f.id)).slice(0,3),count:rows.filter(r=>r.fields.includes(f.id)).length}));}
export function topicsPanel056(s){const h=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return '<details class="guide-input-panel"><summary>Keep other interests in view · optional</summary><p>Choose activities you would like to explore. This changes discovery invitations; it does not confirm a profession or close other fields.</p><div class="form-row">'+discoveryTopics056.map(t=>'<label><input type="checkbox" name="topic056" value="'+t.id+'" '+(activityTopics056(s).some(x=>x.id===t.id)?'checked':'')+'> '+h(t.title)+'</label>').join('')+'</div><button type="button" class="button" data-action="explorer-topics056">Update exploration interests</button></details>';}
export function soundPanel056(s){if(!activityTopics056(s).some(t=>t.id==='sound'))return'';return '<section class="guide-input-panel"><span class="time-chip">Additional activity-led discovery</span><h2>Sound Engineering Technicians</h2><p>Compare recording, mixing and editing sound with your other interests. This is a sourced discovery preview, not a supported Top match. Pay and study costs are not assessed here.</p><p>Training routes vary; a bachelor’s degree is not universal.</p><a href="'+soundPreview056.source+'" target="_blank" rel="noopener">Explore the work · O*NET →</a> · <a href="'+soundPreview056.educationSource+'" target="_blank" rel="noopener">Training routes · BLS →</a></section>';}
